const input = $input.first().json;
const body = input.body ?? input;
const targetDataSource = 'ff0dfdb4-a2ee-497e-b7b4-3eef398c717a';

if (body.verification_token) {
  // Render logs let us retrieve this one-time token without storing it in source.
  console.log(`NOTION_WEBHOOK_VERIFICATION_TOKEN=${body.verification_token}`);
  return [];
}

const allowed = new Set(['page.created', 'page.properties_updated']);
if (!allowed.has(body.type)) return [];
if (body.entity?.type !== 'page' || !body.entity?.id) return [];

// Prevent the Notion metadata patch later in this workflow from feeding back into itself.
if ((body.authors ?? []).some((author) => author?.type === 'bot')) return [];

const normalizeId = (value) => String(value ?? '').replace(/-/g, '').toLowerCase();
const parentDataSource = body.data?.parent?.data_source_id;
if (parentDataSource && normalizeId(parentDataSource) !== normalizeId(targetDataSource)) return [];

return [{
  json: {
    pageId: body.entity.id,
    eventType: body.type,
    webhookEventId: body.id ?? null,
    webhookTimestamp: body.timestamp ?? null
  }
}];

const page = $input.first().json;
const targetDataSource = 'ff0dfdb4-a2ee-497e-b7b4-3eef398c717a';
const normalizeId = (value) => String(value ?? '').replace(/-/g, '').toLowerCase();

if (page.object !== 'page' || !page.id) return [];
if (page.parent?.data_source_id && normalizeId(page.parent.data_source_id) !== normalizeId(targetDataSource)) return [];

const props = page.properties ?? {};
const textValue = (prop) => {
  const parts = prop?.rich_text ?? prop?.title ?? [];
  return parts.map((x) => x?.plain_text ?? x?.text?.content ?? '').join('').trim();
};

const title = textValue(props['Task']) || 'Untitled task';
const calendarName = props['Google Calendar']?.select?.name ?? '';
const eventId = textValue(props['Google Event ID']);
const syncedCalendarId = textValue(props['Synced Calendar ID']);
const dateValue = props['Date']?.date ?? null;
const estimate = Number(props['Estimate (min)']?.number);

const calendars = {
  '🎧 Deep Work': 'thehasnainizhar@gmail.com',
  '🌈 Everything': 'f9ef4f8f551b75e05284f2309a60811a6935a11d0a3ccd41c42737a27be0e3c9@group.calendar.google.com',
  '🤝 Meetings': '0efba785fd021316b372e868e61d6c917b11e5e973e3b254a69dd870749569d5@group.calendar.google.com',
  'Family': 'family14319022949234613336@group.calendar.google.com',
  '🍷 Ventures': '28cba6c2a5ae056b9ce2c84ad90e06f363c7d253888ec67be97f21decdef0b7b@group.calendar.google.com',
};

const targetCalendarId = calendars[calendarName] ?? '';
if (!targetCalendarId || !dateValue?.start) {
  return [{ json: { action: 'skip', reason: 'missing_calendar_or_date', pageId: page.id } }];
}

// Do not invent a time for a date-only task.
if (!String(dateValue.start).includes('T')) {
  return [{ json: { action: 'skip', reason: 'date_only_requires_time', pageId: page.id } }];
}

const start = dateValue.start;
let end = dateValue.end;
if (!end) {
  const minutes = Number.isFinite(estimate) && estimate > 0 ? estimate : 30;
  const startDate = new Date(start);
  if (Number.isNaN(startDate.getTime())) return [];
  end = new Date(startDate.getTime() + minutes * 60_000).toISOString();
}

let action = 'create';
if (eventId) {
  action = syncedCalendarId && syncedCalendarId !== targetCalendarId ? 'move' : 'update';
}

return [{
  json: {
    action,
    pageId: page.id,
    pageUrl: page.url,
    title,
    calendarName,
    targetCalendarId,
    syncedCalendarId,
    eventId,
    start,
    end,
    timezone: 'Asia/Karachi'
  }
}];
